async function validateTranscriptFile(file){
 if(!file||file.size<=0||file.size>20*1024*1024)throw Error('Use a nonempty file up to 20 MB.');
 const ext=file.name.split('.').pop().toLowerCase(),types={pdf:['application/pdf'],png:['image/png'],jpg:['image/jpeg'],jpeg:['image/jpeg'],txt:['text/plain']};
 if(!types[ext])throw Error('Use PDF, JPG, PNG, or TXT.');
 if(file.type&&file.type!=='application/octet-stream'&&!types[ext].includes(file.type))throw Error('File type does not match its extension.');
 const bytes=new Uint8Array(await file.slice(0,1024).arrayBuffer());
 if(ext==='pdf'&&!Array.from(bytes.slice(0,5)).every((b,i)=>b===[37,80,68,70,45][i]))throw Error('This file does not have a valid PDF header.');
 if(ext==='png'&&![137,80,78,71,13,10,26,10].every((b,i)=>bytes[i]===b))throw Error('This file does not have a valid PNG header.');
 if(['jpg','jpeg'].includes(ext)&&!(bytes[0]===255&&bytes[1]===216&&bytes[2]===255))throw Error('This file does not have a valid JPEG header.');
 if(ext==='txt'&&bytes.includes(0))throw Error('This is not a plain-text document.');
 return ext;
}
